            method: 'TRENDHYPERBOLIC',
            minStars: 5,
            backlashIn: 0,
            backlashOut: 0,
            backlashModel: 'OVERSHOOT',
            innerCropRatio: 1.0,
            useBrightestStars: 0,
            // Optical train to auto-focus: 'main' | 'aux' | 'guide'. Pairs the
